import autoSizeInput from "autosize-input";
import { findTagUntil, tagIsDisabled, tagIsSharp, tagIsWrap, findTagByID } from "@/utils/promptTags/util";
import {
    getTagDecWeight,
    getTagIncWeight,
    extractTagValueFromBrackets,
    getTagWeightNum,
    applyTagDecWeight,
    applyTagIncWeight,
    applyTagWeightNum,
} from "@/utils/promptTags/util/tag-weight";
import { getTagClasses } from "@/utils/promptTagRender/tagClasses";
import { renderTagCore } from "@/utils/promptTagRender/renderTag";
import { _createTagBase, _createTagUuid } from "@/utils/promptTags/createTag";
import { parseLoraLikeValue } from "@/utils/promptTags/util/tag-lora";

export default {
    data() {
        return {
            tagClickTimeId: 0,
            showExtendId: '',
        }
    },
    mounted() {
        /*common.gradioApp().addEventListener('mousemove', () => {
            this.$refs.highlightPrompt.hide()
        })*/
    },
    /**
     * 需要在 round-trip / rebuild 中保留的自訂屬性
     * _appendTag() 已處理的屬性（value, localValue, disabled, type）不在此列
     * 新增自訂屬性時只需在此陣列追加
     */
    RESTOREABLE_PROPERTIES: [
        'splitNoComma',
    ],
    methods: {
        _setTag(tag) {
            if (typeof tag['type'] === 'string' && tag.type === 'wrap') {
                tag.weightNum = 1
                tag.incWeight = 0
                tag.decWeight = 0
            } else {
                tag.weightNum = getTagWeightNum(tag.value)
                // tag.weightNum = tag.weightNum <= 0 ? 1 : tag.weightNum
                // tag.weightNum = tag.weightNum === 0 ? 1 : tag.weightNum
                tag.incWeight = getTagIncWeight(tag.value, this)
                tag.decWeight = getTagDecWeight(tag.value)

                tag.originalValue = tag.value
                /** Lora / Lyco 語法偵測：單一事實在 parseLoraLikeValue()，不另行比對正則 */
                if (!parseLoraLikeValue(tag.value)) {
                    // tag.weightNum = tag.weightNum <= 0 ? 1 : tag.weightNum
                    tag.originalValue = extractTagValueFromBrackets(tag.value, this)
                }
            }
            this._setTagClass(tag)
            this.$nextTick(() => {
                this._setTagHeight(tag)
            })
        },
        _setTagHeight(tag) {
            let maxNum = 10
            let interval = setInterval(() => {
                // console.log(maxNum, tag)
                maxNum--
                if (maxNum <= 0) clearInterval(interval)
                if (!this.$refs['promptTagValue-' + tag.id]) return false
                if (!this.$refs['promptTagValue-' + tag.id][0]) return false
                clearInterval(interval)
                let $tag = this.$refs['promptTagValue-' + tag.id][0]
                let height = $tag.offsetHeight
                $tag.parentNode.style.height = height + 'px'
                if (this.$refs['promptTagEdit-' + tag.id]) {
                    this.$refs['promptTagEdit-' + tag.id][0].style.height = height + 'px'
                }
                if (this.$refs['promptTagDelete-' + tag.id]) {
                    this.$refs['promptTagDelete-' + tag.id][0].style.height = height + 'px'
                }
            }, 50)
        },
        _setTagClass(tag) {
            tag.isLora = false
            tag.loraExists = false
            tag.isLyco = false
            tag.lycoExists = false
            tag.isEmbedding = false

            if (typeof tag['type'] === 'string' && tag.type === 'wrap') {
            } else {
                // 判断是否lora / lyco —— 解析單一事實在 parseLoraLikeValue()，
                // 命中的 kind 決定 isLora / isLyco 與對應的名稱欄位
                const parsed = parseLoraLikeValue(tag.value)

                if (parsed) {
                     if (parsed.kind === 'lora') {
                        tag.isLora = true
                        tag.loraName = parsed.name
                        const loraName = this.loraExists(parsed.name)
                        if (loraName !== false) {
                            tag.loraExists = true
                        }
                    }

                    if (parsed.kind === 'lyco') {
                        tag.isLyco = true
                        tag.lycoName = parsed.name
                        const lycoName = this.lycoExists(parsed.name)
                        if (lycoName !== false) {
                            tag.lycoExists = true
                        }
                    }
                }

                if (!tag.isLora && !tag.isLyco) {
                    // 判断是否embedding
                    const embeddingName = this.embeddingExists(tag.value)
                    if (embeddingName !== false) {
                        tag.isEmbedding = true
                        tag.value = embeddingName
                        tag.embeddingName = embeddingName
                    } else {
                        const embeddingName = this.embeddingExists(tag.originalValue)
                        if (embeddingName !== false) {
                            tag.isEmbedding = true
                            // tag.value = embeddingName
                            tag.embeddingName = embeddingName
                        }
                    }
                }
            }

            tag.classes = getTagClasses(tag, this)
            return tag.classes
        },
        _setTagById(id, value = null, localValue = null) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            if (value !== null) tag.value = value
            if (localValue !== null) tag.localValue = localValue
            return tag
        },
        _isTagBlacklist(tag) {
            if (typeof tag['type'] === 'string' && tag.type === 'wrap') return false
            if (tag.isLora) {
                if (this.blacklist.lora?.includes(tag.loraName.toLowerCase())) return true
            } else if (tag.isLyco) {
                if (this.blacklist.lycoris?.includes(tag.lycoName.toLowerCase())) return true
            } else if (tag.isEmbedding) {
                if (this.blacklist.embedding?.includes(tag.embeddingName.toLowerCase())) return true
            } else {
                if (this.neg) {
                    if (this.blacklist.negative_prompt?.includes(tag.originalValue.toLowerCase())) return true
                } else {
                    if (this.blacklist.prompt?.includes(tag.originalValue.toLowerCase())) return true
                }
            }
            return false
        },
        /**
         * 建立一個新 tag 並插入 tags 陣列。
         *
         * @param {string}  value     - 標籤文字
         * @param {string}  localValue - 當地語言翻譯值
         * @param {boolean} disabled   - 是否停用
         * @param {number}  index      - 插入位置（-1 = 末端）
         * @param {string}  type       - 'text' | 'wrap'
         * @param {object}  [opts]     - 可選設定
         * @param {object}  [opts.source] - 舊 tag 或儲存資料；提供時自動還原 RESTOREABLE_PROPERTIES
         * @returns {number} 新 tag 的 index；value 為空字串或命中黑名單時回傳 -1
         */
        _appendTag(value, localValue = '', disabled = false, index = -1, type = 'text', { source } = {}) {
            if (value === '') return -1
            // 唯一数：当前时间戳+随机数
            const id = _createTagUuid()
            const tag = _createTagBase({
                id,
                type,
                value,
                localValue,
                disabled,
            })
            /**
             * * 順序不可調換：黑名單判定必須排在 _setTag() 之後，
             * 因為 _isTagBlacklist() 依賴 _setTag() 才算得出的 isLora / originalValue。
             */
            this._setTag(tag)
            // value           = setLayers(value, 0, '(', ')')
            // value           = setLayers(value, 0, '[', ']')
            if (this._isTagBlacklist(tag)) return -1
            if (index >= 0) {
                // 插入到指定位置
                this.tags.splice(index, 0, tag)
            } else {
                index = this.tags.push(tag)
            }
            // 若提供 source，自動還原自訂屬性（splitNoComma 等）
            if (source) this._restoreTagProperties(tag, source)
            this.$nextTick(() => {
                if (this.$refs['promptTagEdit-' + id]) autoSizeInput(this.$refs['promptTagEdit-' + id][0])
            })
            return index - 1
        },
        /**
         * 從 source 建立 tag，自動還原所有自訂屬性。
         *
         * 透過 _appendTag({ source }) 自動觸發 _restoreTagProperties，
         * 呼叫端無需手動處理。
         * localValue、disabled、type 從 source 提取，無需手動傳入。
         *
         * @param {string} value - 標籤文字
         * @param {number} index - 插入位置（-1 = 末端）
         * @param {object|null} source - 舊 tag 或儲存資料，用於還原屬性
         * @returns {number} 新 tag 的 index，失敗回傳 -1
         */
        _restoreTag(value, index, source) {
            const localValue = source?.localValue || ''
            const disabled = !!source?.disabled
            const type = source?.type || 'text'
            // 透過 _appendTag 的 { source } 參數自動觸發 _restoreTagProperties
            return this._appendTag(value, localValue, disabled, index, type, { source })
        },
        /**
         * 從 source 還原自訂屬性到已建立的 tag 上。
         *
         * 原因：_appendTag() 只建立核心欄位（value, localValue, disabled, type），
         * 但 tag 上可能有其他自訂屬性（如 splitNoComma）需要在 round-trip（儲存→載入）
         * 或 rebuild（textarea 重建）時保留。
         *
         * 做法：只複製 RESTOREABLE_PROPERTIES 中定義的屬性，避免無差別複製
         * 導入 _setTag() 計算的屬性（weightNum/incWeight/decWeight/originalValue 等）。
         * 新增自訂屬性時只需在 RESTOREABLE_PROPERTIES 陣列中追加。
         *
         * 防禦：tag 無效（undefined / -1 index）或 source 為空時直接返回，
         * 不將邊界檢查外洩至呼叫端。
         */
        _restoreTagProperties(tag, source) {
            if (!source || !tag) return
            this.$options.RESTOREABLE_PROPERTIES.forEach(prop => {
                if (source[prop] !== undefined) {
                    tag[prop] = source[prop]
                }
            })
        },
        renderTag(id) {
            return renderTagCore(findTagByID(this.tags, id), this)
        },
        isFavorite(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            if (typeof window.phystonPromptfavorites === 'object') {
                for (const group of window.phystonPromptfavorites) {
                    if (group.key !== this.favoriteKey) continue
                    for (const favorite of group.list) {
                        if (favorite.tags.length !== 1) continue
                        if (favorite.tags[0].value === tag.value) return favorite.id
                    }
                }
            }
            return false
        },
        onLoraPopupUseKeywords(keywords) {
            let indexes = []
            for (let keyword of keywords) {
                let temp = keyword.toLowerCase()
                let find = this.tags.find(tag => tag.value.toLowerCase() === temp)
                if (!find) {
                    let index = this._appendTag(keyword, '', false, -1, 'text')
                    if (index !== -1) indexes.push(index)
                }
            }
            if (indexes.length) {
                this.autoTranslateByIndexes(indexes)
            }
        },
        onTagMouseEnter(id) {
            if (this.isEditing) return false
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            tag.isFavorite = this.isFavorite(tag.id)
            if (this.hotkey.hover === 'extend') this.showExtendId = id
            if (tag.isLora || tag.isLyco || tag.isEmbedding) {
                let name = tag.isLora ? tag.loraName : (tag.isLyco ? tag.lycoName : tag.embeddingName)
                this.$emit('showExtraNetworks', this.$refs['promptTagValue-' + tag.id][0], name, this.onLoraPopupUseKeywords, 'tags')
            }
        },
        onTagMouseMove(id) {
            /*let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            this.$refs.highlightPrompt.show(tag)*/
        },
        onTagMouseLeave(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            if (this.hotkey.hover === 'extend') this.showExtendId = ''
            this.$emit('hideExtraNetworks')
        },
        onTagClick(id) {
            if (this.tagClickTimeId) clearTimeout(this.tagClickTimeId)
            this.tagClickTimeId = setTimeout(() => {
                switch (this.hotkey.click) {
                    case 'edit':
                        this._handleEditTag(id)
                        break
                    case 'disable':
                        this._handleDisableTag(id)
                        break
                    case 'extend':
                        this._handleHoverTag(id)
                        break
                }
                clearTimeout(this.tagClickTimeId)
            }, 250)
        },
        onTagDblclick(id) {
            clearTimeout(this.tagClickTimeId)
            switch (this.hotkey.dblClick) {
                case 'edit':
                    this._handleEditTag(id)
                    break
                case 'disable':
                    this._handleDisableTag(id)
                    break
                case 'extend':
                    this._handleHoverTag(id)
                    break
            }
        },
        /**
         * 雙擊行號（.prompt-tag-line-no）時的行為：
         *
         * - 該行為「空行」（只計算未被停用的 tag）→ 不做任何變更。
         * - 該行第一個 tag 不是 `#` → 在行首插入一個 value 為 `#` 的普通 tag。
         * - 該行第一個 tag 已是 `#` → 切換該 `#` tag 自身的停用狀態。
         *
         * 註：`#` 是普通 tag（value 恰為 `#`），並非特殊型別。
         *
         * @param {string} id - 行首 tag 的 id（line-no 元素的 data-id）
         */
        onLineNumberDblclick(id) {
            const startIndex = this.tags.findIndex(tag => tag.id === id)
            if (startIndex === -1) return

            const firstTag = this.tags[startIndex]

            /**
             * 找出該行結尾：略過所有「非分行」tag，停在第一個分行 tag。
             * 找不到分行 tag 時（最後一行無結尾換行）以陣列末端為界。
             */
            const wrapScan = findTagUntil(this.tags, {
                startIndex,
                ignore: tag => !tagIsWrap(tag),
                untilTarget: tag => tagIsWrap(tag),
            })

            if (tagIsSharp(firstTag)) {
                /** 規則：已是 # → 只切換該 # tag 自身的停用狀態 */
                firstTag.disabled = !firstTag.disabled
            } else {
                const lineEnd = wrapScan.found ? wrapScan.index : this.tags.length
                /** 該行的 tag（不含結尾的分行 tag；行首為分行 tag 時為空陣列） */
                const lineTags = this.tags.slice(startIndex, lineEnd)

                /** 規則：空行（只檢查未被停用的 tag）→ 無任何變化 */
                if (!lineTags.length || !lineTags.some(tag => !tagIsDisabled(tag))) return

                /** 規則：不是 # → 於行首插入 value 為 # 的普通 tag */
                this._appendTag('#', '', false, startIndex, 'text')
            }
            this.updateTags()
        },
        onTagRightClick(id, e) {
            switch (this.hotkey.rightClick) {
                case 'edit':
                    this._handleEditTag(id)
                    break
                case 'disable':
                    this._handleDisableTag(id)
                    break
                case 'extend':
                    this._handleHoverTag(id)
                    break
            }
        },
        _handleEditTag(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            this.editing = {}
            this.editing[tag.id] = true
            this.isEditing = true
            this.$forceUpdate()
            this.$nextTick(() => {
                const input = this.$refs['promptTagEdit-' + tag.id][0]
                input.focus()
                input.dispatchEvent(new Event('input'))
                // input.select()
            })
        },
        _handleDisableTag(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            this.onDisabledTagClick(tag.id)
        },
        _handleHoverTag(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            this.showExtendId = id
        },
        onTagInputBlur(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            this.editing[tag.id] = false
            this.isEditing = false
        },
        onTagInputKeyDown(id, e) {
            if (e.keyCode === 13) {
                let tag = this.tags.find(tag => tag.id === id)
                if (!tag) return false
                this.editing[tag.id] = false
                this.isEditing = false
                this._changeTagValue(tag, e.target.value)
            }
        },
        onTagInputChange(id, e) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            this._changeTagValue(tag, e.target.value)
        },
        _changeTagValue(tag, newValue) {
            let oldValue = tag.value
            if (tag.value !== newValue) {
                tag.value = newValue
                this._setTag(tag)
                if (this._isTagBlacklist(tag)) {
                    tag.value = oldValue
                     this._setTag(tag)
                }
                this.updateTags()
            }
        },
        onTagWeightNumChange(id, e) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            e = typeof e === "number" || typeof e === "string" ? e : e.target.value
            if (tag.weightNum == e) return
            /**
             * 權重語法改寫抽離於 applyTagWeightNum()（參數：tag / options: this）。
             * 回傳 true 代表 value 已改寫、需重算權重欄位；
             * weightNum 必須在 _setTag() 之後寫回，才能蓋過由 value 解析出的數值。
             */
            const changed = applyTagWeightNum(tag, e, this)
            if (changed) this._setTag(tag)
            tag.weightNum = e
            this.updateTags()
        },
        onDeleteTagClick(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            let index = this.tags.indexOf(tag)
            this.tags.splice(index, 1)
            this.updateTags()
        },
        onFavoriteTagClick(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return false
            let favoriteId = this.isFavorite(tag.id)
            if (!favoriteId) {
                // 收藏
                this.gradioAPI.pushFavorite(this.favoriteKey, [tag], tag.value, tag.localValue === '' ? tag.value : tag.localValue).then(res => {
                    if (res) {
                        tag.isFavorite = true
                        this.$emit('refreshFavorites', this.favoriteKey)
                    }
                })
            } else {
                // 取消收藏
                this.gradioAPI.unFavorite(this.favoriteKey, favoriteId).then(res => {
                    if (res) {
                        tag.isFavorite = false
                        this.$emit('refreshFavorites', this.favoriteKey)
                    }
                })
            }
        },
        onDisabledTagClick(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return
            tag.disabled = !tag.disabled
            this.updateTags()
        },
        onIncWeightClick(id, num) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return
            applyTagIncWeight(tag, num, this)
            this.updateTags()
        },
        onDecWeightClick(id, num) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return
            applyTagDecWeight(tag, num, this)
            this.updateTags()
        },
        onWrapTagClick(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return
            let index = this.tags.indexOf(tag)
            let wrapIndex = this._appendTag("\n", "\n", false, -1, 'wrap')
            let wrapTag = this.tags[wrapIndex]
            // 移动到当前标签的下面
            this.tags.splice(wrapIndex, 1);
            // 然后将 'c' 插入到 'e' 后面
            this.tags.splice(index + 1, 0, wrapTag);
            this.updateTags()
        },
        onTranslateToLocalClick(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return
            let index = this.tags.indexOf(tag)
            if (this.loading[tag.id + '_local']) return
            this.translates([index], true, true).finally(() => {
                this.updateTags()
            })
        },
        onTranslateToEnglishClick(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return
            let index = this.tags.indexOf(tag)
            if (this.loading[tag.id + '_en']) return
            this.translates([index], false, true).finally(() => {
                this.updateTags()
            })
        },
        onBlacklistClick(id) {
            let tag = this.tags.find(tag => tag.id === id)
            if (!tag) return

            if (!this.cancelBlacklistConfirm) {
                let title = this.getLang('confirm_add_blacklist').replace('{0}', tag.value) + "\n" + this.getLang('blacklist_desc')
                if (!confirm(title)) return
            }

            let blacklist = JSON.parse(JSON.stringify(this.blacklist))
            if (tag.isLora) {
                blacklist.lora.push(tag.loraName)
            } else if (tag.isLyco) {
                blacklist.lycoris.push(tag.lycoName)
            } else if (tag.isEmbedding) {
                blacklist.embedding.push(tag.embeddingName)
            } else {
                if (this.neg) {
                    blacklist.negative_prompt.push(tag.originalValue)
                } else {
                    blacklist.prompt.push(tag.originalValue)
                }
            }
            this.gradioAPI.setData('blacklist', blacklist)
            this.$emit('update:blacklist', blacklist, this.cancelBlacklistConfirm)

            this.tags.forEach(item => {
                if (item.value === tag.value) {
                    this.onDeleteTagClick(item.id)
                }
            })
        },
    }
}
